// Regenerates src/presets/calm.css and crisp.css from the presets' inputs with the built
// builder (strict mode: a failing pair fails the script). `--check` fails on a diff instead.
// Run after `tsdown` (pnpm --filter @rind-ui/theme presets).
import { readFileSync, writeFileSync } from "node:fs"
import { calm, crisp, defineTheme } from "../dist/builder.mjs"

const header =
  "/* Generated by packages/theme/scripts/build-presets.mjs from src/builder/presets.ts. Do not edit. */\n"
const files = {
  "calm.css": defineTheme({ name: "calm", ...calm, root: true }).css,
  "crisp.css": defineTheme({ name: "crisp", ...crisp }).css,
}
const check = process.argv.includes("--check")
let stale = false
for (const [file, css] of Object.entries(files)) {
  const path = new URL(`../src/presets/${file}`, import.meta.url)
  const text = header + css
  if (check) {
    let current = ""
    try {
      current = readFileSync(path, "utf8")
    } catch {}
    if (current !== text) {
      console.error(`${file} differs from a fresh build: run pnpm --filter @rind-ui/theme presets`)
      stale = true
    }
  } else writeFileSync(path, text)
}
if (stale) process.exit(1)
console.log(check ? "presets up to date" : "presets written")
